write('projects','Projets',intro('Projets','Des espaces.<br>Des caractères.','Une sélection d’intérieurs et de mises en scène. Explorez les détails, les matières et les ambiances à travers les photographies du studio.')+'<section class="wrap" style="padding-top:15px"><div class="filters" aria-label="Filtrer les projets">'+''.join(f'<button type="button" data-filter="{s}" aria-pressed="{str(i==0).lower()}">{s}</button>' for i,s in enumerate(['Tous','Résidentiel','Hospitality','Professionnel','Scénographie','Aménagement']))+'</div><div class="projects-grid">'+cards()+'</div></section><section class="wrap line"><div class="section-head"><span class="eyebrow">Index complet</span><h2>Chaque projet,<br>en un regard.</h2></div>'+rows()+'</section>','projects')
